import path from "node:path";
import { existsSync } from "node:fs";
import { mkdir, readFile, readdir, rm, writeFile } from "node:fs/promises";
import {
  createUnimport,
  toTypeDeclarationFile,
  toTypeReExports,
  type Import,
} from "unimport";
import { autoImportEntries } from "./autoImportEntries";
import { autoImportPackages } from "./autoImportPackages";
import { createPublicImportScanner, scanPublicImports, type PublicImportScanMetrics } from "./autoImportScanner";

const GENERATED_HEADER =
  "// Generated by Thinkly auto-import configuration.\n";
const LEAF_HEADER = `${GENERATED_HEADER}/* eslint-disable */\n/* prettier-ignore */\n// @ts-nocheck\n`;
const MAX_DECLARATION_LINES = 300;
type DeclarationCache = { fingerprint: string; outputs: Map<string, string> };
type GenerationMetrics = PublicImportScanMetrics & { scans: number; generations: number; cacheHits: number; writes: number; leafRenders: number };

function declarationGroup(item: Import, root: string): string {
  const from = path.relative(root, item.from).replaceAll("\\", "/");
  if (from.startsWith("src/components/editor/")) return "editor";
  if (from.startsWith("src/components/ui/")) return "ui";
  if (from.startsWith("src/hooks/")) return "hooks";
  if (from.startsWith("src/stores/")) return "stores";
  if (from.startsWith("src/lib/")) return "lib";
  return "packages";
}

function generateLeaf(imports: Import[], directory: string): string {
  const options = {
    resolvePath(item: Import) {
      const from = item.typeFrom || item.from;
      if (!path.isAbsolute(from)) return from;
      const relative = path
        .relative(directory, from)
        .replaceAll("\\", "/")
        .replace(/\.tsx?$/, "");
      return relative.startsWith(".") ? relative : `./${relative}`;
    },
  };
  const values = imports.filter((item) => !item.type && !item.dtsDisabled);
  const types = imports.filter((item) => item.type);
  return `${LEAF_HEADER}${toTypeDeclarationFile(values, options)}${types.length ? `\n${toTypeReExports(types, options)}` : ""}\n`;
}

/** Declaration line counts only grow as imports are appended (including grouped type exports). */
export function splitDeclarationImports(imports: Import[], directory: string, rendered?: () => void): string[] {
  const leaves: string[] = [];
  for (let start = 0; start < imports.length;) {
    let low = 1, high = imports.length - start, size = 0, content = "";
    while (low <= high) {
      const middle = Math.floor((low + high) / 2);
      rendered?.();
      const candidate = generateLeaf(imports.slice(start, start + middle), directory);
      if (candidate.trimEnd().split("\n").length <= MAX_DECLARATION_LINES) {
        size = middle; content = candidate; low = middle + 1;
      } else high = middle - 1;
    }
    // Preserve the linear splitter's behavior for one item already over the limit.
    if (!size) { size = 1; rendered?.(); content = generateLeaf(imports.slice(start, start + 1), directory); }
    leaves.push(content); start += size;
  }
  return leaves;
}

async function writeIfChanged(file: string, content: string, cache?: DeclarationCache, metrics?: GenerationMetrics) {
  const current = await readFile(file, "utf8").catch(() => "");
  if (current !== content) {
    await writeFile(file, content, "utf8");
    if (metrics) metrics.writes++;
  }
  cache?.outputs.set(file, content);
}

async function outputsMatch(root: string, cache: DeclarationCache) {
  for (const [file, content] of cache.outputs) {
    if (await readFile(file, "utf8").catch(() => null) !== content) return false;
  }
  const directory = path.join(root, "src/auto-imports");
  for (const name of await readdir(directory).catch(() => [])) {
    const file = path.join(directory, name);
    if (name.endsWith(".d.ts") && !cache.outputs.has(file) &&
        (await readFile(file, "utf8")).startsWith(GENERATED_HEADER)) return false;
  }
  return true;
}

function assertUniquePublicImports(imports: Import[]) {
  const names = new Map<string, Import>();
  for (const item of imports) {
    const key = `${item.as ?? item.name}:${Boolean(item.type)}`;
    const previous = names.get(key);
    if (
      previous &&
      (previous.from !== item.from || previous.name !== item.name)
    ) {
      throw new Error(
        `[auto-import] 公共符号 ${item.as ?? item.name} 同时从 ${previous.from} 和 ${item.from} 导出。请保留唯一公开入口。`,
      );
    }
    names.set(key, item);
  }
}

/** 无缓存调用始终完整扫描；开发会话只重扫 dirty 命中的公开入口。 */
export async function generateAutoImportDeclarations(root: string, cache?: DeclarationCache, metrics?: GenerationMetrics,
  paths: string[] | null = null, scanner?: ReturnType<typeof createPublicImportScanner>) {
  const missing = autoImportEntries.filter(
    (entry) => !existsSync(path.join(root, entry)),
  );
  if (missing.length) {
    throw new Error(
      `[auto-import] 公共入口已不存在，请更新 autoImportEntries：${missing.join(", ")}`,
    );
  }
  const packageImports = Object.entries(autoImportPackages).flatMap(
    ([from, names]) => names.map((name) => ({ from, name, as: name })),
  );
  if (metrics) metrics.scans++;
  // Keep unimport's export-star resolution and type scan as the authority.
  const scanned = scanner ? await scanner.scan(paths) : await scanPublicImports(autoImportEntries, root);
  assertUniquePublicImports([...packageImports, ...scanned]);
  const fingerprint = JSON.stringify([packageImports, scanned]);
  if (cache?.fingerprint === fingerprint && await outputsMatch(root, cache)) {
    if (metrics) metrics.cacheHits++;
    return;
  }
  if (metrics) metrics.generations++;
  // Publish the fingerprint only after every output has been written successfully.
  const nextCache: DeclarationCache | undefined = cache && { fingerprint, outputs: new Map() };
  const unimport = createUnimport({ imports: packageImports });
  await unimport.modifyDynamicImports(() => scanned);
  const imports = await unimport.getImports();
  const directory = path.join(root, "src/auto-imports");
  await mkdir(directory, { recursive: true });
  const groups = new Map<string, Import[]>();
  for (const item of imports) {
    const group = declarationGroup(item, root);
    groups.set(group, [...(groups.get(group) ?? []), item]);
  }
  const files: string[] = [];
  for (const [group, items] of [...groups].sort(([a], [b]) =>
    a.localeCompare(b),
  )) {
    items.sort((a, b) =>
      `${a.from}:${a.as}:${a.type}`.localeCompare(
        `${b.from}:${b.as}:${b.type}`,
      ),
    );
    let part = 1;
    for (const content of splitDeclarationImports(items, directory, () => { if (metrics) metrics.leafRenders++; })) {
      const filename = `${group}-${part++}.d.ts`;
      files.push(filename);
      await writeIfChanged(
        path.join(directory, filename),
        content,
        nextCache, metrics,
      );
    }
  }
  for (const filename of await readdir(directory)) {
    if (!filename.endsWith(".d.ts") || files.includes(filename)) continue;
    const file = path.join(directory, filename);
    if ((await readFile(file, "utf8")).startsWith(GENERATED_HEADER))
      await rm(file);
  }
  await writeIfChanged(
    path.join(root, "src/auto-imports.d.ts"),
    GENERATED_HEADER +
      files
        .map(
          (file) => `import "./auto-imports/${file.replace(/\.d\.ts$/, "")}";`,
        )
        .join("\n") +
      "\n",
    nextCache, metrics,
  );
  if (cache && nextCache) Object.assign(cache, nextCache);
}

/** Build/add/unlink request a full refresh; changes reuse each entry's resolved export-star dependencies. */
export function createAutoImportDeclarationGenerator(root: string) {
  const cache: DeclarationCache = { fingerprint: "", outputs: new Map() };
  const metrics: GenerationMetrics = { scans: 0, generations: 0, cacheHits: 0, writes: 0, leafRenders: 0,
    entryScans: 0, dependencyReads: 0, typeParses: 0 };
  const scanner = createPublicImportScanner(autoImportEntries, root, metrics);
  return { metrics, generate: (paths: string[] | null = null) => generateAutoImportDeclarations(root, cache, metrics, paths, scanner) };
}
